<div class="row g-4 recurring-deposit-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Monthly Deposit ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="rd-dep" class="form-control form-control-lg" value="500" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Annual Rate (%)</label><div class="input-group"><input type="number" id="rd-rate" class="form-control form-control-lg" value="7" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">Term (Months)</label><div class="input-group"><input type="number" id="rd-term" class="form-control form-control-lg" value="36" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Compounding (per yr)</label><div class="input-group"><input type="number" id="rd-comp" class="form-control form-control-lg" value="4" min="0"></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:140;--tool-color:#22c55e;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Recurring Deposit Calculator</span><div class="output-hero-value" id="recurring-val">—</div><span class="output-hero-unit" id="recurring-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#22c55e;background:rgba(0,0,0,.02);"><span class="stat-card-label">MATURITY VALUE</span><span class="stat-card-value" style="color:#22c55e" id="rd-mat">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">TOTAL INVESTED</span><span class="stat-card-value" style="color:#3b82f6" id="rd-invested">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#f59e0b;background:rgba(0,0,0,.02);"><span class="stat-card-label">INTEREST EARNED</span><span class="stat-card-value" style="color:#f59e0b" id="rd-interest">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#a855f7;background:rgba(0,0,0,.02);"><span class="stat-card-label">EFFECTIVE YIELD</span><span class="stat-card-value" style="color:#a855f7" id="rd-eff">—</span></div></div></div><div class="mt-4" id="recurring-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="recurring-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="recurring-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="recurring-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const dep=parseFloat($("rd-dep").value)||0,rate=(parseFloat($("rd-rate").value)||0)/100,term=parseFloat($("rd-term").value)||1,comp=parseFloat($("rd-comp").value)||4;const n=comp,r=rate/n,t2=term/12;const invested=dep*term;let mat=0;for(let m=1;m<=term;m++){mat+=dep*Math.pow(1+r,n*(term-m)/12);}const interest=mat-invested;const eff=invested>0?(interest/invested*100):0;$("recurring-val").textContent=fmt(mat);$("rd-mat").textContent=fmt(mat);$("rd-invested").textContent=fmt(invested);$("rd-interest").textContent=fmt(interest);$("rd-eff").textContent=eff.toFixed(1)+"%";$("recurring-st").textContent="MATURITY VALUE";$("recurring-st").style.color="#22c55e";let ins=[];ins.push("Invest "+fmt(dep)+"/mo for "+term+" months → <strong>"+fmt(mat)+"</strong> at maturity.");ins.push("Total invested: "+fmt(invested)+". Interest earned: <strong>"+fmt(interest)+"</strong>.");$("recurring-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['rd-dep','rd-rate','rd-term','rd-comp'].forEach(id=>$(id).addEventListener("input",calc));$("recurring-cb").addEventListener("click",calc);$("recurring-cp").addEventListener("click",function(){navigator.clipboard.writeText("Recurring Deposit Calculator: "+$("recurring-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("recurring-rs").addEventListener("click",()=>{$("rd-dep").value=500;$("rd-rate").value=7;$("rd-term").value=36;$("rd-comp").value=4;calc();});calc();});</script>
<style>.recurring-deposit-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.recurring-deposit-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.recurring-deposit-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.recurring-deposit-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.recurring-deposit-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.recurring-deposit-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style>